# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN (SAV) GENÇLERLE İLETİŞİM İLKELERİ (PH.6.2.1)</text>\n  <rect x="20" y="46" width="210" height="194" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Sevgi, Şefkat ve Anlayış</text>\n  <text x="32" y="96" font-size="11.5" fill="#1e3a8a">• Gençleri hiçbir zaman</text>\n  <text x="32" y="114" font-size="11.5" fill="#1e3a8a">  azarlamamış ve kırmamıştır.</text>\n  <text x="32" y="138" font-size="11.5" fill="#1e3a8a">• Onlara «Yavrucuğum!» diye</text>\n  <text x="32" y="156" font-size="11.5" fill="#1e3a8a">  şefkatle hitap etmiştir.</text>\n  <text x="32" y="180" font-size="11.5" fill="#1e3a8a">• Hatalarını ikna ve tatlı</text>\n  <text x="32" y="198" font-size="11.5" fill="#1e3a8a">  dille düzeltmiştir.</text>\n  <text x="125" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Gönül Kazanan İletişim</text>\n\n  <rect x="245" y="46" width="210" height="194" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. İstişare (Görüş Alışverişi)</text>\n  <text x="257" y="96" font-size="11.5" fill="#14532d">• Gençlerin fikirlerine değer</text>\n  <text x="257" y="114" font-size="11.5" fill="#14532d">  verip onlara danışmıştır.</text>\n  <text x="257" y="138" font-size="11.5" fill="#14532d">• Hendek Savaşı\'nda genç sahabi</text>\n  <text x="257" y="156" font-size="11.5" fill="#14532d">  Selmân-ı Fârisî\'nin hendek</text>\n  <text x="257" y="174" font-size="11.5" fill="#14532d">  önerisini kabul etmiştir.</text>\n  <text x="257" y="198" font-size="11.5" fill="#14532d">• Uhud\'da gençlerin görüşüne</text>\n  <text x="257" y="214" font-size="11.5" fill="#14532d">  uyarak meydan savaşı yapmıştır.</text>\n\n  <rect x="470" y="46" width="210" height="194" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="70" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Güven ve Sorumluluk</text>\n  <text x="482" y="96" font-size="11.5" fill="#713f12">• Gençlere yeteneklerine göre</text>\n  <text x="482" y="114" font-size="11.5" fill="#713f12">  önemli görevler vermiştir:</text>\n  <text x="482" y="138" font-size="11.5" fill="#713f12">  • Tebliğ ve Öğretmenlik</text>\n  <text x="482" y="158" font-size="11.5" fill="#713f12">  • Vahiy Kâtipliği ve Elçilik</text>\n  <text x="482" y="178" font-size="11.5" fill="#713f12">  • Valilik ve Kadılık</text>\n  <text x="482" y="198" font-size="11.5" fill="#713f12">  • Sancaktarlık ve Komutanlık</text>\n  <text x="575" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Tebliğ · İstişare · Cihat</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN YETİŞTİRDİĞİ ÖRNEK GENÇ SAHABİLER (1)</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Mus\'ab bin Umeyr (ra) — İlk Öğretmen</text>\n  <text x="40" y="98" font-size="11.5" fill="#831843">• Mekke\'nin en zengin ve zarif genci iken</text>\n  <text x="40" y="116" font-size="11.5" fill="#831843">  inancı uğruna tüm servetini terk etti.</text>\n  <text x="40" y="138" font-size="11.5" fill="#831843">• I. Akabe Biatı\'ndan sonra Medine\'ye</text>\n  <text x="40" y="156" font-size="11.5" fill="#831843">  «İslam\'ın ilk öğretmeni» olarak gönderildi.</text>\n  <text x="40" y="178" font-size="11.5" fill="#831843">• Uhud Savaşı\'nda İslam sancağını</text>\n  <text x="40" y="196" font-size="11.5" fill="#831843">  korurken şehadet mertebesine ulaştı.</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Fedakârlık, Tebliğ ve Şehadet Örneği</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Muâz bin Cebel (ra) — Genç Vali ve Âlim</text>\n  <text x="375" y="98" font-size="11.5" fill="#581c87">• Henüz 18 yaşında Müslüman oldu;</text>\n  <text x="375" y="116" font-size="11.5" fill="#581c87">  Kur\'an ve fıkıh ilminde zirveye ulaştı.</text>\n  <text x="375" y="138" font-size="11.5" fill="#581c87">• Peygamberimiz (sav) onu «Ümmetimin helal</text>\n  <text x="375" y="156" font-size="11.5" fill="#581c87">  ve haramı en iyi bileni» olarak övdü.</text>\n  <text x="375" y="178" font-size="11.5" fill="#581c87">• Genç yaşta Yemen\'e vali, kadı (hâkim)</text>\n  <text x="375" y="196" font-size="11.5" fill="#581c87">  ve öğretmen olarak görevlendirildi.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#581c87">İlim, Hikmet ve Adalet Örneği</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN YETİŞTİRDİĞİ ÖRNEK GENÇ SAHABİLER (2)</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Üsâme bin Zeyd (ra) — Genç Komutan</text>\n  <text x="40" y="98" font-size="11.5" fill="#155e75">• Peygamberimizin çok sevdiği Zeyd bin</text>\n  <text x="40" y="116" font-size="11.5" fill="#155e75">  Hârise\'nin (ra) oğludur («Hibbü Resûlillah»).</text>\n  <text x="40" y="138" font-size="11.5" fill="#155e75">• Henüz 18-19 yaşlarında iken Bizans</text>\n  <text x="40" y="156" font-size="11.5" fill="#155e75">  sınırına gönderilecek ordunun</text>\n  <text x="40" y="174" font-size="11.5" fill="#155e75">  başkomutanlığına tayin edildi.</text>\n  <text x="40" y="196" font-size="11.5" fill="#155e75">• Liyakat ve cesaretiyle örnek oldu.</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Cesaret, Liyakat ve Komutanlık</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">Esma bint Ebî Bekir (ra) ve Diğer Gençler</text>\n  <text x="375" y="98" font-size="11.5" fill="#9a3412">• Esma bint Ebî Bekir (ra): Hicrette Sevr</text>\n  <text x="375" y="116" font-size="11.5" fill="#9a3412">  Mağarası\'na erzak taşıdı; kuşağını ikiye</text>\n  <text x="375" y="134" font-size="11.5" fill="#9a3412">  böldüğü için «Zâtü\'n-Nitâkayn» unvanı aldı.</text>\n  <text x="375" y="158" font-size="11.5" fill="#9a3412">• Erkam bin Ebî\'l-Erkam: Evini (Dârü\'l-Erkam)</text>\n  <text x="375" y="176" font-size="11.5" fill="#9a3412">  genç yaşta İslam tebliğine açtı.</text>\n  <text x="375" y="198" font-size="11.5" fill="#9a3412">• Zeyd bin Sâbit: Genç vahiy kâtibi oldu.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">Dârü\'l-Erkam: Gençlerin Eğitim Merkezi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
